请对以下 case 进行三维加权评分。

=== case_id ===
Case-08-sleep-001

=== 用户原始指令 (query.txt) ===
整个睡眠周报 主体是个曲线图 点一下能跳进去 能从日历读日程 显示已连接

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "整个睡眠周报 主体是个曲线图 点一下能跳进去 能从日历读日程 显示已连接",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "huaweischeme://healthapp/router/sleepDetail"
      }
    }
  ],
  "dataModelSchema": {
    "sleep": {
      "weekTitle": {
        "type": "string",
        "description": "睡眠周报标题",
        "sampleValue": "睡眠周报"
      },
      "durationText": {
        "type": "string",
        "description": "本周平均睡眠时长展示文本",
        "sampleValue": "7h32m"
      },
      "qualityText": {
        "type": "string",
        "description": "本周睡眠质量状态",
        "sampleValue": "规律提升"
      },
      "sparkline": {
        "type": "string",
        "description": "本周睡眠曲线的紧凑字符图",
        "sampleValue": "▁▃▅▆▇▆▇"
      },
      "avgText": {
        "type": "string",
        "description": "本周平均值说明",
        "sampleValue": "均值 7.5h"
      },
      "trendText": {
        "type": "string",
        "description": "本周睡眠趋势说明",
        "sampleValue": "较上周 +18m"
      }
    },
    "device": {
      "connectionText": {
        "type": "string",
        "description": "设备连接确认状态",
        "sampleValue": "已连接"
      }
    },
    "data": {
      "calendar": {
        "items": [
          {
            "entityId": {
              "type": "string",
              "description": "日程索引项唯一标识符",
              "sampleValue": "calendar-event-001"
            },
            "title": {
              "type": "string",
              "description": "下一条日程标题",
              "sampleValue": "晨间复盘"
            },
            "dtStart": {
              "type": "string",
              "description": "下一条日程开始时间",
              "sampleValue": "09:30"
            },
            "dtEnd": {
              "type": "string",
              "description": "下一条日程结束时间",
              "sampleValue": "10:00"
            }
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_sleep.png",
      "description": "睡眠监督图标，适合用于睡眠周报卡片的服务识别和夜间场景视觉锚点。"
    }
  ]
}

